# Chapter 24 Magnetic fields and electromagnetism — part a: 24.1 to 24.4.
MU0 = 4 * pi * 1e-7
GW = 2e-7          # µ₀/2π in T m A⁻¹
MU = ' Take µ₀/2π = 2.0 × 10⁻⁷ T m A⁻¹.'
MUS = ' Take µ₀ = 4π × 10⁻⁷ T m A⁻¹.'

# ═════════════════════════ 24.1 Magnetic fields due to currents (15/17/10) ═════════════════════════
lesson('24.1')
M('E', 1, 'How does the spacing of the field lines around a long straight current-carrying wire change with distance from the wire?', 'The circles get further apart, showing a weaker field', ['The circles get closer together, showing a stronger field', 'The spacing stays the same', 'The lines become straight'], 'The field strength falls with distance, so the concentric circles are drawn further apart.')
M('E', 1, 'How is the right-hand grip rule used for a solenoid?', 'Curl the fingers in the direction of the current in the turns; the thumb points to the north-pole end', ['Point the thumb along the current; the fingers point to the south pole', 'Point the fingers along the field; the thumb gives the force', 'Curl the fingers along the field; the thumb gives the current'], 'For a coil or solenoid, the thumb gives the direction of the field inside, which leaves at the north end.')
M('E', 1, 'The current in a straight wire is reversed. What happens to its magnetic field?', 'The field direction reverses but its pattern stays the same', ['The field disappears', 'The field becomes stronger', 'The circles become straight lines'], 'The direction of the field circles follows the direction of the current.')
M('E', 1, 'Why is a soft iron core placed inside a solenoid to make an electromagnet?', 'It makes the magnetic field very much stronger', ['It reduces the current', 'It makes the field permanent', 'It stops the field reversing'], 'Iron is easily magnetised and greatly concentrates the field, and soft iron loses its magnetism when the current stops.')
N('E', 2, 'The magnetic flux density a distance r from a long straight wire is B = µ₀I/2πr. Calculate B at 0.020 m from a wire carrying 5.0 A, in µT.' + MU, GW * 5.0 / 0.020 * 1e6, 'µT',
  'B = 2.0 × 10⁻⁷ × 5.0 ÷ 0.020 = 5.0 × 10⁻⁵ T. In µT: 5.0 × 10⁻⁵ × 10⁶ = 50', ['C1: B = µ₀I/2πr'], sig=2, aq='B')
N('E', 2, 'The flux density inside a long solenoid is B = µ₀nI, where n is the number of turns per metre. Calculate B for n = 2000 m⁻¹ and I = 1.5 A, in mT.' + MUS, MU0 * 2000 * 1.5 * 1000, 'mT',
  f'B = 4π × 10⁻⁷ × 2000 × 1.5 = {sf(MU0 * 3000)} T. In mT: {sf(MU0 * 3000, 4)} × 1000 = {sf(MU0 * 3000 * 1000)}', ['C1: B = µ₀nI'], aq='B')
M('E', 1, 'What is the direction of the magnetic field at the centre of a flat circular coil carrying a current?', 'Perpendicular to the plane of the coil', ['In the plane of the coil, along a diameter', 'Around the wire in circles only', 'There is no field at the centre'], 'The contributions from every part of the coil point the same way through the centre, along its axis.')
M('E', 1, 'What is the main advantage of an electromagnet over a permanent magnet?', 'Its field can be switched off and its strength changed by changing the current', ['It never needs a power supply', 'It is always stronger', 'It works without a core'], 'B depends on the current, which can be controlled.')
N('E', 2, 'The flux density 4.0 cm from a long straight wire is 30 µT. What is it 8.0 cm from the wire, in µT? (B ∝ 1/r.)', 30 * 4.0 / 8.0, 'µT',
  'B ∝ 1/r, so doubling r halves B: 30 × 4.0 ÷ 8.0 = 15 µT', ['C1: B ∝ 1/r'], sig=2, aq='B')
M('E', 1, 'Looking at one end of a solenoid, you see the current flowing anticlockwise. Which pole is at that end?', 'North', ['South', 'Neither: there are no poles', 'It depends on the length of the solenoid'], 'Anticlockwise current seen from an end makes that end a north pole (grip rule).')
N('E', 2, 'A solenoid has 500 turns wound evenly along a length of 0.25 m. Calculate the number of turns per metre, n.', 500 / 0.25, 'm⁻¹',
  'n = N/L = 500 ÷ 0.25 = 2000 m⁻¹', ['C1: n = N/L'], sig=2, aq='n')
M('E', 1, 'Where is the magnetic field of a long solenoid strongest?', 'Inside the solenoid, away from its ends', ['Just outside the middle of the solenoid', 'Far from the solenoid', 'At the centre of each turn of wire only'], 'Inside, the fields of all the turns add; outside they largely cancel.')
N('E', 2, 'A solenoid has 4000 turns per metre. Calculate the current needed to give a flux density of 2.0 mT inside it, using B = µ₀nI.' + MUS, 2.0e-3 / (MU0 * 4000), 'A',
  f'I = B/(µ₀n) = 2.0 × 10⁻³ ÷ (4π × 10⁻⁷ × 4000) = {sf(2e-3 / (MU0 * 4000))} A', ['C1: I = B/(µ₀n)'], aq='I')
M('E', 1, 'In which direction do magnetic field lines point outside a bar magnet?', 'From the north pole to the south pole', ['From the south pole to the north pole', 'Towards both poles', 'Away from both poles'], 'Field lines show the direction a free north pole would move.')
N('E', 1, 'The flux density inside a solenoid is 0.60 mT. The current is tripled. What is the new flux density, in mT?', 1.8, 'mT', 'B ∝ I: 3 × 0.60 = 1.8 mT', [], sig=2, aq='B')
# medium
N('M', 3, 'A compass needle lies where the Earth\'s horizontal field is 2.0 × 10⁻⁵ T due north. A nearby wire adds a horizontal field of 1.5 × 10⁻⁵ T due east. Calculate the angle the needle turns through from north.', degrees(atan(1.5 / 2.0)), '°',
  f'The needle lines up with the resultant field: tan θ = 1.5 × 10⁻⁵ ÷ 2.0 × 10⁻⁵ = 0.75, so θ = tan⁻¹ 0.75 = {sf(degrees(atan(0.75)))}°', ['M1: needle follows resultant', 'C1: tan θ = B_wire/B_Earth'], aq='θ')
N('M', 3, 'How far from a long straight wire carrying 10 A is the flux density 1.0 × 10⁻⁵ T? (B = µ₀I/2πr.)' + MU, GW * 10 / 1.0e-5, 'm',
  'r = (µ₀/2π) × I ÷ B = 2.0 × 10⁻⁷ × 10 ÷ 1.0 × 10⁻⁵ = 0.20 m', ['C1: rearranged for r', 'C1: substitution'], sig=2, aq='r')
N('M', 4, 'Two long parallel wires are 10 cm apart and each carries 4.0 A, in opposite directions. Calculate the flux density midway between them, in µT. (B = µ₀I/2πr for each wire.)' + MU, 2 * GW * 4.0 / 0.050 * 1e6, 'µT',
  'Each wire gives B = 2.0 × 10⁻⁷ × 4.0 ÷ 0.050 = 1.6 × 10⁻⁵ T. With opposite currents the fields point the same way between the wires: B = 2 × 1.6 × 10⁻⁵ = 3.2 × 10⁻⁵ T. In µT: 3.2 × 10⁻⁵ × 10⁶ = 32', ['C1: field of one wire', 'M1: fields add for opposite currents', 'C1: total'], sig=2, aq='B')
M('M', 3, 'Two long parallel wires carry equal currents in the same direction. What is the magnetic field midway between them?', 'Zero, because the two fields are equal and opposite there', ['Twice the field of one wire', 'The same as the field of one wire', 'It points along the wires'], 'Between the wires, same-direction currents produce opposite field directions.', ['C1: equal magnitudes at midpoint', 'C1: opposite directions'])
N('M', 3, 'A solenoid 0.40 m long has 800 turns and carries 2.5 A. Calculate the flux density inside it, in mT, using B = µ₀nI.' + MUS, MU0 * 800 / 0.40 * 2.5 * 1000, 'mT',
  f'n = 800 ÷ 0.40 = 2000 m⁻¹. B = 4π × 10⁻⁷ × 2000 × 2.5 = {sf(MU0 * 5000)} T. In mT: {sf(MU0 * 5000, 4)} × 1000 = {sf(MU0 * 5000 * 1000)}', ['C1: n = N/L', 'C1: B = µ₀nI'], aq='B')
N('M', 3, 'What current in a long straight wire produces a flux density equal to the Earth\'s field, 5.0 × 10⁻⁵ T, at a distance of 5.0 cm? (B = µ₀I/2πr.)' + MU, 5.0e-5 * 0.050 / GW, 'A',
  'I = B × r ÷ (µ₀/2π) = 5.0 × 10⁻⁵ × 0.050 ÷ 2.0 × 10⁻⁷ = 12.5 A', ['C1: rearranged for I', 'C1: substitution'], aq='I')
M('M', 3, 'A solenoid is stretched to twice its length without changing the number of turns or the current. What happens to the flux density inside?', 'It halves', ['It doubles', 'It stays the same', 'It quarters'], 'B = µ₀nI and n = N/L halves.', ['C1: n = N/L halves', 'C1: B ∝ n'])
N('M', 3, 'The flux density 3.0 cm from a long straight wire is 120 µT. Calculate the flux density 9.0 cm from the wire, in µT.', 120 * 3.0 / 9.0, 'µT',
  'B ∝ 1/r: B = 120 × 3.0 ÷ 9.0 = 40 µT', ['C1: B ∝ 1/r', 'C1: ratio'], sig=2, aq='B')
M('M', 3, 'The field pattern of a flat circular coil carrying a current most closely resembles that of which object?', 'A short bar magnet', ['A long straight wire', 'Two like poles facing each other', 'A uniform field'], 'One face acts as a north pole and the other as a south pole.', ['C1: poles on the two faces', 'C1: like a short magnet'])
N('M', 3, 'A solenoid 0.30 m long must produce 10 mT when carrying 3.0 A. Using B = µ₀NI/L, calculate the number of turns needed.' + MUS, 10e-3 * 0.30 / (MU0 * 3.0), 'turns',
  f'N = BL/(µ₀I) = 10 × 10⁻³ × 0.30 ÷ (4π × 10⁻⁷ × 3.0) = {sf(10e-3 * 0.3 / (MU0 * 3))} turns', ['C1: rearranged for N', 'C1: substitution'], aq='N')
M('M', 4, 'A long vertical wire carries a current upwards. The Earth\'s horizontal field points north. On which side of the wire is there a point where the resultant horizontal field is zero?', 'West of the wire', ['East of the wire', 'North of the wire', 'South of the wire'], 'Viewed from above, the wire\'s field circles anticlockwise. To the west of the wire it points south, opposing the Earth\'s northward field.', ['C1: grip rule direction', 'C1: wire field opposite to Earth field', 'C1: west side'])
N('M', 3, 'The flux density at the centre of a flat circular coil is B = µ₀NI/2r. Calculate B for a coil of 50 turns and radius 0.10 m carrying 2.0 A, in mT.' + MUS, MU0 * 50 * 2.0 / (2 * 0.10) * 1000, 'mT',
  f'B = 4π × 10⁻⁷ × 50 × 2.0 ÷ (2 × 0.10) = {sf(MU0 * 100 / 0.2)} T. In mT: {sf(MU0 * 100 / 0.2, 4)} × 1000 = {sf(MU0 * 100 / 0.2 * 1000)}', ['C1: B = µ₀NI/2r', 'C1: substitution'], aq='B')
N('M', 3, 'A laboratory solenoid gives a flux density of 3.0 mT. The Earth\'s field is about 5.0 × 10⁻⁵ T. Calculate (solenoid field) ÷ (Earth\'s field).', 3.0e-3 / 5.0e-5, None,
  'Ratio = 3.0 × 10⁻³ ÷ 5.0 × 10⁻⁵ = 60', ['C1: both in tesla', 'C1: ratio'], sig=2, aq='ratio')
M('M', 3, 'A horizontal wire runs west to east and carries a current towards the east. What is the direction of its magnetic field at a point directly above the wire?', 'Due south', ['Due north', 'Vertically upwards', 'Due east'], 'With the thumb pointing east, the fingers of the right hand curl over the top of the wire towards the south (seen from the west end, the field circles clockwise).', ['C1: right-hand grip rule', 'C1: direction above the wire'])
N('M', 4, 'At a point near a wire, the wire produces a horizontal field of 3.0 × 10⁻⁵ T due west and the Earth\'s horizontal field is 4.0 × 10⁻⁵ T due north. Calculate the magnitude of the resultant horizontal field, in µT.', 50, 'µT',
  'B = √((3.0 × 10⁻⁵)² + (4.0 × 10⁻⁵)²) = 5.0 × 10⁻⁵ T. In µT: 5.0 × 10⁻⁵ × 10⁶ = 50', ['M1: fields add as vectors', 'C1: Pythagoras', 'C1: conversion'], sig=2, aq='B')
M('M', 3, 'Which change would NOT increase the strength of an electromagnet made from a coil and core?', 'Replacing the iron core with a copper core', ['Increasing the current', 'Adding more turns per metre', 'Using a soft iron core instead of air'], 'Copper is not ferromagnetic, so it does not concentrate the field.', ['C1: B ∝ nI', 'C1: copper not magnetic'])
N('M', 3, 'The flux density 6.0 cm from a long straight wire is 40 µT. Calculate the current in the wire. (B = µ₀I/2πr.)' + MU, 40e-6 * 0.060 / GW, 'A',
  'I = B × r ÷ (µ₀/2π) = 40 × 10⁻⁶ × 0.060 ÷ 2.0 × 10⁻⁷ = 12 A', ['C1: rearranged for I', 'C1: substitution'], sig=2, aq='I')
# hard
N('H', 6, 'Two long parallel wires are 0.10 m apart. Wire 1 carries 6.0 A and wire 2 carries 2.0 A in the same direction. (a) Explain why the resultant field is zero at one point between the wires. (b) Write an equation for the distance x of this point from wire 1, using B = µ₀I/2πr. (c) Calculate x, in cm. Give only the answer to (c).', 0.6 / 8 * 100, 'cm',
  '(a) Between same-direction currents the two fields are opposite; they are equal where the larger current is further away. (b) 6.0/x = 2.0/(0.10 − x). (c) 6.0 × (0.10 − x) = 2.0x, so x = 0.60 ÷ 8.0 = 0.075 m. In cm: 0.075 × 100 = 7.5',
  ['B1: fields opposite between wires', 'M1: equal magnitudes', 'C1: equation', 'C1: x = 0.075 m', 'C1: conversion'], sig=2, aq='x')
N('H', 6, 'A compass is placed 4.0 cm from a long vertical wire, on the line east of it. The wire\'s field there is horizontal and at right angles to the Earth\'s horizontal field B_E. Readings: I/A = 1.0, 2.0, 3.0, 4.0 and deflection θ/° = 15.5, 29.1, 39.8, 48.0. (a) Show that tan θ = µ₀I/(2πrB_E). (b) Calculate tan θ for the largest reading and use it to find B_E, in µT. Give only the answer to (b).' + MU, GW * 4.0 / 0.040 / tan(radians(48.0)) * 1e6, 'µT',
  f'(a) The needle follows the resultant of B_E and the wire\'s field B_w at right angles, so tan θ = B_w/B_E = µ₀I/(2πrB_E). (b) tan 48.0° = {sf(tan(radians(48)), 4)}. B_w = 2.0 × 10⁻⁷ × 4.0 ÷ 0.040 = 2.0 × 10⁻⁵ T. B_E = 2.0 × 10⁻⁵ ÷ {sf(tan(radians(48)), 4)} = {sf(2e-5 / tan(radians(48)))} T. In µT: {sf(2e-5 / tan(radians(48)), 4)} × 10⁶ = {sf(2e-5 / tan(radians(48)) * 1e6)}',
  ['M1: resultant of perpendicular fields', 'B1: tan θ expression', 'C1: wire field', 'C1: B_E = B_w/tan θ', 'C1: conversion'], aq='B_E')
N('H', 6, 'A solenoid 0.50 m long must produce a flux density of 25 mT. The wire can safely carry 4.0 A. (a) Using B = µ₀NI/L, calculate the number of turns needed. (b) Each turn uses 0.15 m of wire and the wire has a resistance of 0.020 Ω per metre. Calculate the resistance of the solenoid. (c) Calculate the p.d. needed across it. Give only the answer to (a).' + MUS, 25e-3 * 0.50 / (MU0 * 4.0), 'turns',
  f'(a) N = BL/(µ₀I) = 25 × 10⁻³ × 0.50 ÷ (4π × 10⁻⁷ × 4.0) = {sf(25e-3 * 0.5 / (MU0 * 4))} turns. (b) Length = {sf(25e-3 * 0.5 / (MU0 * 4), 4)} × 0.15 = {sf(25e-3 * 0.5 / (MU0 * 4) * 0.15)} m; R = {sf(25e-3 * 0.5 / (MU0 * 4) * 0.15, 4)} × 0.020 = {sf(25e-3 * 0.5 / (MU0 * 4) * 0.15 * 0.02)} Ω. (c) V = IR = 4.0 × {sf(25e-3 * 0.5 / (MU0 * 4) * 0.15 * 0.02, 4)} = {sf(4 * 25e-3 * 0.5 / (MU0 * 4) * 0.15 * 0.02)} V',
  ['C1: N = BL/(µ₀I)', 'C1: substitution', 'C1: wire length', 'C1: resistance', 'C1: V = IR'], aq='N')
N('H', 6, 'Two long parallel wires A and B, 5.0 cm apart, each carry 6.0 A out of the page. Point P is 3.0 cm from A and 4.0 cm from B, so AP and BP are at right angles. (a) Calculate the flux density at P due to each wire, using B = µ₀I/2πr. (b) Explain why these two fields are at right angles to each other at P. (c) Calculate the resultant flux density at P, in µT. Give only the answer to (c).' + MU, sqrt((GW * 6 / 0.03) ** 2 + (GW * 6 / 0.04) ** 2) * 1e6, 'µT',
  '(a) B_A = 2.0 × 10⁻⁷ × 6.0 ÷ 0.030 = 4.0 × 10⁻⁵ T; B_B = 2.0 × 10⁻⁷ × 6.0 ÷ 0.040 = 3.0 × 10⁻⁵ T. (b) Each field is perpendicular to the line from its wire to P, and those lines are perpendicular. (c) B = √((4.0 × 10⁻⁵)² + (3.0 × 10⁻⁵)²) = 5.0 × 10⁻⁵ T. In µT: 5.0 × 10⁻⁵ × 10⁶ = 50',
  ['C1: B_A', 'C1: B_B', 'B1: fields perpendicular', 'M1: vector addition', 'C1: conversion'], sig=2, aq='B')
N('H', 5, 'A long vertical wire carries 8.0 A. The Earth\'s horizontal field is 2.0 × 10⁻⁵ T. (a) Explain why there is a neutral point near the wire. (b) Calculate the distance of the neutral point from the wire, in cm. Give only the answer to (b).' + MU, GW * 8.0 / 2.0e-5 * 100, 'cm',
  '(a) On one side of the wire its circular field is opposite to the Earth\'s field; where the magnitudes are equal the resultant is zero. (b) µ₀I/2πr = B_E, so r = 2.0 × 10⁻⁷ × 8.0 ÷ 2.0 × 10⁻⁵ = 0.080 m. In cm: 0.080 × 100 = 8.0',
  ['B1: opposite fields on one side', 'M1: µ₀I/2πr = B_E', 'C1: r', 'C1: conversion'], sig=2, aq='r')
N('H', 6, 'A solenoid of length 0.60 m and radius 1.5 cm has 1200 turns and carries 0.50 A. A 50-turn search coil is wound tightly round its middle. (a) Calculate the flux density inside the solenoid, using B = µ₀NI/L. (b) Calculate the flux through the solenoid\'s cross-section. (c) Calculate the flux linkage of the search coil. Give only the answer to (c).' + MUS, 50 * MU0 * 2000 * 0.5 * pi * 0.015 ** 2, 'Wb',
  f'(a) B = 4π × 10⁻⁷ × (1200 ÷ 0.60) × 0.50 = {sf(MU0 * 1000)} T. (b) A = π × 0.015² = {sf(pi * 0.015 ** 2)} m²; Φ = {sf(MU0 * 1000, 4)} × {sf(pi * 0.015 ** 2, 4)} = {sf(MU0 * 1000 * pi * 0.015 ** 2)} Wb. (c) NΦ = 50 × {sf(MU0 * 1000 * pi * 0.015 ** 2, 4)} = {sf(50 * MU0 * 1000 * pi * 0.015 ** 2)} Wb',
  ['C1: n = N/L', 'C1: B = µ₀nI', 'C1: A = πr²', 'C1: Φ = BA', 'C1: NΦ'], aq='NΦ')
N('H', 6, 'A Hall probe measures the field at distances r from a long straight wire: r/cm = 2.0, 4.0, 6.0, 8.0 and B/µT = 100, 50, 33, 25. (a) Show that B is inversely proportional to r. (b) Calculate the value of Br. (c) Use B = µ₀I/2πr to find the current in the wire. Give only the answer to (c).' + MU, 100e-6 * 0.020 / GW, 'A',
  '(a) Br = 100 × 0.020 = 2.0 µT m for every reading (33 × 0.060 = 1.98), so B ∝ 1/r. (b) Br = 100 × 10⁻⁶ × 0.020 = 2.0 × 10⁻⁶ T m. (c) I = Br ÷ (µ₀/2π) = 2.0 × 10⁻⁶ ÷ 2.0 × 10⁻⁷ = 10 A',
  ['C1: Br calculated', 'B1: constant, so B ∝ 1/r', 'M1: Br = µ₀I/2π', 'C1: substitution', 'C1: value'], sig=2, aq='I')
N('H', 5, 'A flat coil of 100 turns and radius 5.0 cm carries 0.40 A. (a) Calculate the flux density at its centre using B = µ₀NI/2r. (b) The same wire is rewound as a solenoid of 100 turns and length 0.20 m. Calculate the flux density inside, using B = µ₀NI/L. (c) Calculate (flat-coil field) ÷ (solenoid field). Give only the answer to (c).' + MUS, (MU0 * 100 * 0.40 / 0.10) / (MU0 * 100 * 0.40 / 0.20), None,
  f'(a) B = 4π × 10⁻⁷ × 100 × 0.40 ÷ 0.10 = {sf(MU0 * 40 / 0.1)} T. (b) B = 4π × 10⁻⁷ × 100 × 0.40 ÷ 0.20 = {sf(MU0 * 40 / 0.2)} T. (c) Ratio = {sf(MU0 * 40 / 0.1, 4)} ÷ {sf(MU0 * 40 / 0.2, 4)} = 2.0',
  ['C1: flat coil field', 'C1: solenoid field', 'C1: ratio', 'B1: comparison of 2r and L'], sig=2, aq='ratio')
N('H', 5, 'An overhead power cable carries a steady current of 300 A at a height of 10 m above the ground. (a) Calculate the flux density it produces at ground level directly below, in µT, using B = µ₀I/2πr. (b) Compare this with the Earth\'s field of about 50 µT. (c) Explain why the field from a mains cable alternates. Give only the answer to (a).' + MU, GW * 300 / 10 * 1e6, 'µT',
  '(a) B = 2.0 × 10⁻⁷ × 300 ÷ 10 = 6.0 × 10⁻⁶ T. In µT: 6.0 × 10⁻⁶ × 10⁶ = 6.0. (b) It is about an eighth of the Earth\'s field. (c) Mains current alternates, so the field reverses direction 100 times a second.',
  ['C1: B = µ₀I/2πr', 'C1: conversion', 'B1: comparison', 'B1: alternating current gives alternating field'], sig=2, aq='B')
N('H', 6, 'Two long parallel wires, 0.20 m apart, carry 5.0 A each in opposite directions. Point P lies on the line through both wires, 0.10 m outside wire 1 (so 0.30 m from wire 2). (a) Calculate the flux density at P due to each wire, using B = µ₀I/2πr. (b) Explain whether the two fields add or subtract at P. (c) Calculate the resultant flux density at P, in µT. Give only the answer to (c).' + MU, (GW * 5 / 0.10 - GW * 5 / 0.30) * 1e6, 'µT',
  f'(a) B₁ = 2.0 × 10⁻⁷ × 5.0 ÷ 0.10 = 1.0 × 10⁻⁵ T; B₂ = 2.0 × 10⁻⁷ × 5.0 ÷ 0.30 = {sf(GW * 5 / 0.3)} T. (b) Outside the pair, opposite currents give opposite field directions, so they subtract. (c) B = 1.0 × 10⁻⁵ − {sf(GW * 5 / 0.3, 4)} = {sf(GW * 5 / 0.1 - GW * 5 / 0.3)} T. In µT: {sf(GW * 5 / 0.1 - GW * 5 / 0.3, 4)} × 10⁶ = {sf((GW * 5 / 0.1 - GW * 5 / 0.3) * 1e6)}',
  ['C1: B₁', 'C1: B₂', 'B1: fields opposite outside the pair', 'M1: subtract', 'C1: conversion'], aq='B')

# ═════════════════════════ 24.2 Force on a current-carrying conductor (16/15/11) ═════════════════════════
lesson('24.2')
M('E', 1, 'In Fleming\'s left-hand rule, what does the second finger represent?', 'The conventional current', ['The magnetic field', 'The force (motion)', 'The flow of electrons'], 'First finger: Field; seCond finger: Current; thuMb: Motion (force).')
N('E', 2, 'A 0.050 m length of wire carrying 2.5 A lies at right angles to a uniform field of 0.80 T. Calculate the force on it.', 0.80 * 2.5 * 0.050, 'N',
  'F = BIL = 0.80 × 2.5 × 0.050 = 0.10 N', ['C1: F = BIL'], sig=2, aq='F')
M('E', 1, 'For a given current and field, when is the force on a straight wire in a magnetic field greatest?', 'When the wire is at right angles to the field', ['When the wire is parallel to the field', 'When the wire is at 45° to the field', 'The force does not depend on direction'], 'F = BIL sin θ is largest when θ = 90°.')
N('E', 2, 'A 0.15 m wire lies at right angles to a 0.20 T field and experiences a force of 0.045 N. Calculate the current in the wire.', 0.045 / (0.20 * 0.15), 'A',
  'I = F/(BL) = 0.045 ÷ (0.20 × 0.15) = 1.5 A', ['C1: I = F/(BL)'], sig=2, aq='I')
M('E', 1, 'A horizontal wire carries a current due north in a magnetic field that points vertically downwards. In which direction is the force on the wire?', 'Due west', ['Due east', 'Vertically upwards', 'Due south'], 'Fleming\'s left-hand rule: first finger down, second finger north, thumb points west.')
N('E', 2, 'A 0.30 m wire carrying 2.0 A lies at 60° to a uniform field of 0.50 T. Calculate the force on it.', 0.50 * 2.0 * 0.30 * sin(radians(60)), 'N',
  f'F = BIL sin θ = 0.50 × 2.0 × 0.30 × sin 60° = {sf(0.3 * sin(radians(60)))} N', ['C1: F = BIL sin θ'], aq='F')
M('E', 1, 'Which change would double the force on a current-carrying wire at right angles to a uniform field?', 'Doubling the current', ['Halving the length of wire in the field', 'Turning the wire to lie along the field', 'Reversing the current'], 'F = BIL, so with B and L fixed the force is proportional to the current.')
N('E', 2, 'A power cable carries 500 A at right angles to the Earth\'s magnetic field of 5.0 × 10⁻⁵ T. Calculate the force on each metre of cable.', 5.0e-5 * 500, 'N m⁻¹',
  'F/L = BI = 5.0 × 10⁻⁵ × 500 = 0.025 N m⁻¹', ['C1: F/L = BI'], sig=2, aq='F/L')
M('E', 1, 'Why does a current-carrying coil in a magnetic field rotate?', 'The forces on opposite sides are equal and opposite but along different lines, forming a couple', ['The field pulls the coil towards the north pole', 'The current heats the coil', 'The coil becomes a permanent magnet'], 'Opposite currents in the two sides give opposite forces, producing a turning effect.')
N('E', 2, 'In a school motor kit, a 0.020 m section of wire carrying 3.0 A at right angles to the field between the magnets feels a force of 0.012 N. What is the flux density?', 0.012 / (3.0 * 0.020), 'T',
  'B = F/(IL) = 0.012 ÷ (3.0 × 0.020) = 0.20 T', ['C1: B = F/(IL)'], sig=2, aq='B')
M('E', 1, 'Only the current in a wire in a magnetic field is reversed. What happens to the force on the wire?', 'It reverses direction', ['It doubles', 'It becomes zero', 'It stays the same'], 'The force direction depends on the current direction (left-hand rule).')
N('E', 2, 'Calculate the force on a 4.0 cm length of wire carrying 8.0 A at right angles to a field of 0.15 T.', 0.15 * 8.0 * 0.040, 'N',
  'F = BIL = 0.15 × 8.0 × 0.040 = 0.048 N', ['C1: F = BIL with L in m'], sig=2, aq='F')
M('E', 1, 'Why does a current-carrying wire lying along the field lines feel no force?', 'The force depends on sin θ, and θ = 0 when the wire is parallel to the field', ['The current is too small', 'Magnetic fields only act on magnets', 'The wire is not magnetic'], 'F = BIL sin θ = 0 when θ = 0.')
N('E', 2, 'Between the poles of a 60 mT magnet, 0.10 m of a lead carrying 0.50 A crosses the field at right angles. Find the force on it, in mN.', 60e-3 * 0.50 * 0.10 * 1000, 'mN',
  'F = BIL = 60 × 10⁻³ × 0.50 × 0.10 = 3.0 × 10⁻³ N. In mN: 3.0 × 10⁻³ × 1000 = 3.0', ['C1: F = BIL with B in T'], sig=2, aq='F')
M('E', 1, 'In a "catapult field" diagram, why is a current-carrying wire pushed sideways?', 'Its circular field adds to the uniform field on one side and cancels it on the other; the wire is pushed towards the weaker side', ['The field lines pull the wire towards the stronger side', 'The wire is attracted to the north pole', 'The field lines pass through the wire'], 'The combined field is strong on one side and weak on the other, like a stretched catapult.')
N('E', 1, 'A wire at right angles to a field feels a force of 0.20 N. What force does it feel when turned to 30° to the field?', 0.20 * sin(radians(30)), 'N',
  'F ∝ sin θ, so F = 0.20 × sin 30° = 0.10 N', [], sig=2, aq='F')
# medium
N('M', 3, 'A straight wire in a uniform field feels a force of 0.10 N when perpendicular to the field. At what angle to the field must it be placed to feel a force of 0.050 N?', degrees(asin(0.50)), '°',
  'sin θ = 0.050 ÷ 0.10 = 0.50, so θ = sin⁻¹ 0.50 = 30°', ['C1: F = F_max sin θ', 'C1: inverse sine'], sig=2, aq='θ')
N('M', 3, 'A loudspeaker coil has 50 turns of radius 1.5 cm in a radial magnetic field of 0.80 T, which is at right angles to the wire everywhere. Calculate the force on the coil when the current is 0.20 A.', 0.80 * 0.20 * 50 * 2 * pi * 0.015, 'N',
  f'Total length L = 50 × 2π × 0.015 = {sf(50 * 2 * pi * 0.015)} m. F = BIL = 0.80 × 0.20 × {sf(50 * 2 * pi * 0.015, 4)} = {sf(0.16 * 50 * 2 * pi * 0.015)} N', ['C1: total length of wire', 'C1: F = BIL'], aq='F')
M('M', 3, 'A beam of electrons travels east through a magnetic field. To apply Fleming\'s left-hand rule, which way should the second finger point?', 'West, because conventional current is opposite to electron flow', ['East, along the electron beam', 'Along the field', 'Vertically upwards'], 'The rule uses conventional current, which flows opposite to the electrons.', ['C1: conventional current', 'C1: opposite to electron motion'])
N('M', 4, 'A horizontal copper wire with a mass of 0.020 kg per metre lies at right angles to a horizontal magnetic field of 0.25 T. Calculate the current needed for the magnetic force to support its weight.' + take('g'), 0.020 * g / 0.25, 'A',
  f'For each metre, BIL = mg: I = mg/(BL) = 0.020 × 9.81 ÷ (0.25 × 1.0) = {sf(0.02 * 9.81 / 0.25)} A', ['M1: magnetic force = weight', 'C1: per metre', 'C1: substitution'], aq='I')
N('M', 3, 'A rectangular coil of 20 turns has sides of length 0.050 m at right angles to a 0.40 T field. The coil carries 1.5 A. Calculate the force on one of these sides.', 20 * 0.40 * 1.5 * 0.050, 'N',
  'F = NBIL = 20 × 0.40 × 1.5 × 0.050 = 0.60 N', ['C1: force on each turn', 'C1: × number of turns'], sig=2, aq='F')
N('M', 4, 'The two 0.050 m sides of a 20-turn coil each feel a force of 0.60 N in opposite directions. The sides are 0.040 m apart. Calculate the torque on the coil.', 0.60 * 0.040, 'N m',
  'Torque of a couple = one force × perpendicular separation = 0.60 × 0.040 = 0.024 N m', ['M1: forces form a couple', 'C1: torque = F × d', 'C1: substitution'], sig=2, aq='torque')
M('M', 3, 'Why does a simple d.c. motor need a split-ring commutator?', 'It reverses the current in the coil every half turn, so the couple keeps turning the coil the same way', ['It increases the current', 'It stops the coil overheating', 'It keeps the field direction constant'], 'Without it, the forces would reverse their turning effect after half a revolution.', ['C1: reverses current each half-turn', 'C1: maintains rotation direction'])
N('M', 3, 'A metal rod of mass 0.010 kg rests across two horizontal rails 0.080 m apart. A current of 5.0 A flows through it, and a vertical field of 0.30 T acts. Ignoring friction, calculate the acceleration of the rod.', 0.30 * 5.0 * 0.080 / 0.010, 'm s⁻²',
  'F = BIL = 0.30 × 5.0 × 0.080 = 0.12 N. a = F/m = 0.12 ÷ 0.010 = 12 m s⁻²', ['C1: F = BIL', 'C1: a = F/m'], sig=2, aq='a')
M('M', 3, 'A wire is at an angle θ to a uniform magnetic field. Which component of the field produces the force on the wire?', 'The component perpendicular to the wire, B sin θ', ['The component parallel to the wire, B cos θ', 'Both components equally', 'Neither: only the current matters'], 'The parallel component exerts no force, so F = (B sin θ)IL.', ['C1: perpendicular component', 'C1: B sin θ'])
N('M', 3, 'A 50 m span of overhead cable carries 300 A at 40° to the Earth\'s field of 4.0 × 10⁻⁵ T. Calculate the force on the span.', 4.0e-5 * 300 * 50 * sin(radians(40)), 'N',
  f'F = BIL sin θ = 4.0 × 10⁻⁵ × 300 × 50 × sin 40° = {sf(4e-5 * 300 * 50 * sin(radians(40)))} N', ['C1: F = BIL sin θ', 'C1: substitution'], aq='F')
M('M', 4, 'On a diagram, a uniform field points from left to right across the page, and a wire carries a current into the page. In which direction is the force on the wire?', 'Towards the bottom of the page', ['Towards the top of the page', 'To the right', 'Out of the page'], 'Left-hand rule: first finger right, second finger into the page, thumb points down the page.', ['C1: field right', 'C1: current into page', 'C1: thumb down'])
N('M', 3, 'A 0.050 m length of wire at right angles to a 0.10 T field experiences a force of 2.5 mN. Calculate the current.', 2.5e-3 / (0.10 * 0.050), 'A',
  'I = F/(BL) = 2.5 × 10⁻³ ÷ (0.10 × 0.050) = 0.50 A', ['C1: force in N', 'C1: I = F/(BL)'], sig=2, aq='I')
N('M', 4, 'A straight wire 0.40 m long carries 2.0 A at right angles to a field of 0.30 T, but only half of its length lies inside the field. Calculate the force on the wire.', 0.30 * 2.0 * 0.20, 'N',
  'Only the length in the field counts: L = 0.20 m. F = BIL = 0.30 × 2.0 × 0.20 = 0.12 N', ['B1: only length in field', 'C1: L = 0.20 m', 'C1: F = BIL'], sig=2, aq='F')
M('M', 3, 'A wire at right angles to a field is turned until it is at 45° to the field. By what factor does the force change?', 'It is multiplied by about 0.71', ['It is halved', 'It stays the same', 'It is multiplied by about 1.4'], 'F ∝ sin θ: sin 45° = 0.71.', ['C1: F ∝ sin θ', 'C1: sin 45°'])
N('M', 3, 'A horizontal copper wire has a mass of 1.0 × 10⁻³ kg per metre and lies at right angles to the Earth\'s horizontal field of 5.0 × 10⁻⁵ T. Calculate the current needed for the magnetic force to support the wire.' + take('g'), 1.0e-3 * g / 5.0e-5, 'A',
  f'I = mg/(BL) per metre = 1.0 × 10⁻³ × 9.81 ÷ 5.0 × 10⁻⁵ = {sf(1e-3 * 9.81 / 5e-5)} A: far too large for such a thin wire', ['M1: BIL = mg', 'C1: substitution'], aq='I')
# hard
N('H', 6, 'A horizontal wire 0.050 m long and of mass 3.0 g hangs from two light vertical conductors in a vertical magnetic field of 0.20 T. A current of 2.0 A is passed through it, and the wire swings sideways until the conductors make an angle θ with the vertical. (a) Calculate the magnetic force on the wire. (b) Calculate its weight. (c) Calculate θ. Give only the answer to (c).' + take('g'), degrees(atan(0.20 * 2.0 * 0.050 / (3.0e-3 * g))), '°',
  f'(a) F = BIL = 0.20 × 2.0 × 0.050 = 0.020 N, horizontal. (b) W = 3.0 × 10⁻³ × 9.81 = {sf(3e-3 * 9.81)} N. (c) tan θ = F/W = 0.020 ÷ {sf(3e-3 * 9.81, 4)} = {sf(0.02 / (3e-3 * 9.81), 4)}, so θ = tan⁻¹ {sf(0.02 / (3e-3 * 9.81), 4)} = {sf(degrees(atan(0.02 / (3e-3 * 9.81))))}°',
  ['C1: F = BIL', 'C1: weight in N', 'M1: tan θ = F/W', 'C1: substitution', 'B1: force horizontal, perpendicular to field'], aq='θ')
N('H', 5, 'A rectangular coil of 100 turns, 0.040 m long and 0.030 m wide, carries 0.25 A. The 0.040 m sides are at right angles to a uniform field of 0.15 T. (a) Calculate the force on each 0.040 m side. (b) Calculate the maximum torque on the coil. (c) State the position of the coil when the torque is a maximum. Give only the answer to (b).', 100 * 0.15 * 0.25 * 0.040 * 0.030, 'N m',
  '(a) F = NBIL = 100 × 0.15 × 0.25 × 0.040 = 0.15 N. (b) Maximum torque = F × width = 0.15 × 0.030 = 4.5 × 10⁻³ N m. (c) When the plane of the coil is parallel to the field, so the forces are furthest apart.',
  ['C1: F = NBIL', 'M1: couple', 'C1: torque = F × d', 'B1: plane parallel to field'], sig=2, aq='torque')
N('H', 6, 'In a model rail gun, a rod of mass 0.020 kg lies across two rails 0.10 m apart in a vertical field of 0.50 T. A current of 4.0 A flows through the rod, and a friction force of 0.050 N opposes its motion. (a) Calculate the magnetic force on the rod. (b) Calculate the acceleration. (c) Calculate its speed after moving 0.80 m from rest. Give only the answer to (c).', sqrt(2 * (0.50 * 4.0 * 0.10 - 0.050) / 0.020 * 0.80), 'm s⁻¹',
  f'(a) F = BIL = 0.50 × 4.0 × 0.10 = 0.20 N. (b) a = (0.20 − 0.050) ÷ 0.020 = 7.5 m s⁻². (c) v = √(2as) = √(2 × 7.5 × 0.80) = {sf(sqrt(12))} m s⁻¹',
  ['C1: F = BIL', 'C1: resultant force', 'C1: a = F/m', 'M1: v² = 2as', 'C1: substitution'], aq='v')
N('H', 5, 'A 0.50 m wire lies along the x-axis carrying 3.0 A in the +x direction. A uniform field of 0.40 T lies in the x–y plane at 30° to the x-axis. (a) Calculate the force on the wire and state its direction. (b) The wire is turned to lie along the y-axis. Calculate the new force. (c) State an orientation of the wire, in the x–y plane, that gives zero force. Give only the answer to (b).', 0.40 * 3.0 * 0.50 * sin(radians(60)), 'N',
  f'(a) F = 0.40 × 3.0 × 0.50 × sin 30° = 0.30 N, along the z-axis (perpendicular to both wire and field). (b) The angle between wire and field is now 60°: F = 0.40 × 3.0 × 0.50 × sin 60° = {sf(0.6 * sin(radians(60)))} N. (c) Along the field direction, at 30° to the x-axis.',
  ['C1: F = BIL sin 30°', 'B1: direction perpendicular to both', 'C1: angle now 60°', 'B1: parallel gives zero'], aq='F')
N('H', 6, 'An electromagnetic pump moves liquid sodium along a channel 0.050 m wide and 0.020 m high. A current of 200 A passes across the 0.050 m width, at right angles to both the flow and a magnetic field of 0.30 T. (a) Calculate the force on the sodium in the field region. (b) Calculate the pressure difference this produces along the channel. (c) Explain why this pump has no moving parts. Give only the answer to (b).', 0.30 * 200 * 0.050 / (0.050 * 0.020), 'Pa',
  '(a) F = BIL = 0.30 × 200 × 0.050 = 3.0 N. (b) The force acts over the channel cross-section 0.050 × 0.020 = 1.0 × 10⁻³ m², so p = 3.0 ÷ 1.0 × 10⁻³ = 3.0 × 10³ Pa. (c) The liquid metal itself carries the current, so the magnetic force acts directly on the fluid.',
  ['C1: F = BIL', 'C1: cross-sectional area', 'M1: p = F/A', 'C1: value', 'B1: force acts on the conducting liquid'], sig=2, aq='p')
N('H', 5, 'A loudspeaker coil of 80 turns and diameter 2.5 cm sits in a radial field of 1.2 T, at right angles to the wire everywhere. (a) Calculate the total length of wire in the field. (b) Calculate the force on the coil when the current is 0.50 A. (c) The coil and cone have a combined mass of 10 g. Calculate their acceleration, ignoring other forces. Give only the answer to (b).', 1.2 * 0.50 * 80 * pi * 0.025, 'N',
  f'(a) L = 80 × π × 0.025 = {sf(80 * pi * 0.025)} m. (b) F = BIL = 1.2 × 0.50 × {sf(80 * pi * 0.025, 4)} = {sf(0.6 * 80 * pi * 0.025)} N. (c) a = F/m = {sf(0.6 * 80 * pi * 0.025, 4)} ÷ 0.010 = {sf(0.6 * 80 * pi * 0.025 / 0.01)} m s⁻²',
  ['C1: circumference × turns', 'C1: F = BIL', 'C1: a = F/m', 'B1: mass in kg'], aq='F')
N('H', 6, 'A student measures the force on a 0.040 m length of wire at right angles to a magnetic field for different currents: I/A = 1.0, 2.0, 3.0, 4.0 and F/mN = 2.4, 4.9, 7.2, 9.7. (a) Describe the relationship between F and I. (b) Calculate the gradient of the F–I graph using the first and last readings. (c) Calculate the flux density, in mT. Give only the answer to (c).', (9.7 - 2.4) * 1e-3 / 3.0 / 0.040 * 1000, 'mT',
  f'(a) F ∝ I: a straight line through the origin. (b) Gradient = (9.7 − 2.4) × 10⁻³ ÷ (4.0 − 1.0) = {sf(7.3e-3 / 3)} N A⁻¹. (c) Gradient = BL, so B = {sf(7.3e-3 / 3, 4)} ÷ 0.040 = {sf(7.3e-3 / 3 / 0.04)} T. In mT: {sf(7.3e-3 / 3 / 0.04, 4)} × 1000 = {sf(7.3e-3 / 3 / 0.04 * 1000)}',
  ['B1: F ∝ I', 'C1: gradient', 'M1: gradient = BL', 'C1: B', 'C1: conversion'], aq='B')
N('H', 5, 'A square coil of 50 turns and side 0.060 m carries 1.2 A in a uniform field of 0.20 T. (a) Show that the maximum torque is NBIA. (b) Calculate the maximum torque. (c) State the torque when the plane of the coil is perpendicular to the field, and explain. Give only the answer to (b).', 50 * 0.20 * 1.2 * 0.060 ** 2, 'N m',
  f'(a) Each side of length a feels NBIa; the couple arm is a, so torque = NBIa × a = NBIA. (b) Torque = 50 × 0.20 × 1.2 × 0.060² = {sf(50 * 0.2 * 1.2 * 0.0036)} N m. (c) Zero: the forces on opposite sides then act along the same line.',
  ['M1: force on side × arm', 'B1: NBIA shown', 'C1: substitution', 'B1: zero torque, forces in line'], aq='torque')
N('H', 6, 'A copper rod 0.30 m long and of mass 0.045 kg hangs horizontally from two springs, at right angles to a horizontal magnetic field of 0.60 T. (a) State the direction of the magnetic force needed to remove the tension in the springs. (b) Calculate the current needed. (c) Explain what happens to the springs if the current is reversed. Give only the answer to (b).' + take('g'), 0.045 * g / (0.60 * 0.30), 'A',
  f'(a) Vertically upwards, to balance the weight. (b) BIL = mg, so I = 0.045 × 9.81 ÷ (0.60 × 0.30) = {sf(0.045 * 9.81 / 0.18)} A. (c) The force reverses and acts downwards, so the springs stretch further, with tension 2mg in total.',
  ['B1: upward force', 'M1: BIL = mg', 'C1: substitution', 'C1: value', 'B1: springs stretch more'], aq='I')
N('H', 5, 'A wire is bent into a semicircle of radius 0.10 m and placed in a uniform field of 0.50 T at right angles to the plane of the semicircle. A current of 2.0 A flows in it. (a) Explain why the resultant force on the semicircle equals the force on a straight wire joining its ends. (b) Calculate this resultant force. Give only the answer to (b).', 0.50 * 2.0 * 0.20, 'N',
  '(a) The force on each small element is perpendicular to it; adding them, the components along the diameter cancel and the rest add to the force on the straight chord. (b) F = BI × 2r = 0.50 × 2.0 × 0.20 = 0.20 N',
  ['B1: components cancel by symmetry', 'M1: effective length = diameter', 'C1: F = BIL', 'C1: value'], sig=2, aq='F')
N('H', 6, 'A horizontal wire 2.0 m long carrying 50 A from east to west experiences a vertical force of 2.0 mN due to the Earth\'s field. (a) State which component of the Earth\'s field produces this force. (b) Calculate this component, in µT. (c) The wire is turned to run north–south, and the Earth\'s vertical component is 4.4 × 10⁻⁵ T. Calculate the new force, in mN. Give only the answer to (b).', 2.0e-3 / (50 * 2.0) * 1e6, 'µT',
  '(a) The horizontal (northward) component, which is at right angles to an east–west wire. (b) B_h = F/(IL) = 2.0 × 10⁻³ ÷ (50 × 2.0) = 2.0 × 10⁻⁵ T. In µT: 2.0 × 10⁻⁵ × 10⁶ = 20. (c) Now only the vertical component is perpendicular to the wire and gives a horizontal force: F = 4.4 × 10⁻⁵ × 50 × 2.0 = 4.4 × 10⁻³ N, which is 4.4 mN.',
  ['B1: horizontal component', 'C1: B = F/(IL)', 'C1: conversion', 'M1: vertical component for N–S wire', 'C1: new force'], sig=2, aq='B')

# ═════════════════════════ 24.3 Magnetic fields and flux density (16/16/10) ═════════════════════════
lesson('24.3')
M('E', 1, 'Which statement defines magnetic flux density B?', 'The force per unit current per unit length on a wire at right angles to the field', ['The force per unit charge on a stationary charge', 'The number of field lines through a coil', 'The current per unit length of a solenoid'], 'B = F/(IL) with the wire perpendicular to the field.')
M('E', 1, 'Which unit is equivalent to the tesla?', 'N A⁻¹ m⁻¹', ['N A m', 'A N⁻¹ m⁻¹', 'N C⁻¹'], 'B = F/(IL), so 1 T = 1 N A⁻¹ m⁻¹.')
N('E', 2, 'A 0.30 m wire carrying 1.5 A at right angles to a uniform field feels a force of 0.090 N. Calculate the flux density.', 0.090 / (1.5 * 0.30), 'T',
  'B = F/(IL) = 0.090 ÷ (1.5 × 0.30) = 0.20 T', ['C1: B = F/(IL)'], sig=2, aq='B')
N('E', 2, 'A square loop of side 0.25 m sits face-on to a uniform field of 0.12 T. Calculate the magnetic flux through the loop.', 0.12 * 0.25 ** 2, 'Wb',
  'Φ = BA = 0.12 × 0.25² = 7.5 × 10⁻³ Wb', ['C1: Φ = BA'], sig=2, aq='Φ')
M('E', 1, 'Which unit is equivalent to the weber?', 'T m²', ['T m⁻²', 'T m', 'N A⁻¹'], 'Φ = BA, so 1 Wb = 1 T m².')
N('E', 2, 'The Earth\'s field of 50 µT passes at right angles through a window of area 2.0 m². Calculate the flux through the window.', 50e-6 * 2.0, 'Wb',
  'Φ = BA = 50 × 10⁻⁶ × 2.0 = 1.0 × 10⁻⁴ Wb', ['C1: Φ = BA with B in T'], sig=2, aq='Φ')
M('E', 1, 'How is a uniform magnetic field represented on a diagram?', 'By parallel, equally spaced field lines', ['By concentric circles', 'By radial lines', 'By lines that get closer together'], 'Equal spacing shows equal strength; parallel lines show the same direction everywhere.')
N('E', 2, 'Each turn of a 300-turn pickup coil has a flux of 2.0 × 10⁻⁴ Wb through it. What is the total flux linkage?', 300 * 2.0e-4, 'Wb',
  'NΦ = 300 × 2.0 × 10⁻⁴ = 0.060 Wb', ['C1: flux linkage = NΦ'], sig=2, aq='NΦ')
M('E', 1, 'In which orientation is the flux through a flat coil in a uniform field greatest?', 'When the plane of the coil is at right angles to the field', ['When the plane of the coil is parallel to the field', 'When the coil is at 45° to the field', 'The flux is the same in all orientations'], 'Φ = BA cos θ, where θ is the angle between the field and the normal to the coil.')
N('E', 2, 'A field of 0.30 T makes an angle of 30° with the normal to a coil of area 0.010 m². Calculate the flux through the coil.', 0.30 * 0.010 * cos(radians(30)), 'Wb',
  f'Φ = BA cos θ = 0.30 × 0.010 × cos 30° = {sf(0.003 * cos(radians(30)))} Wb', ['C1: Φ = BA cos θ'], aq='Φ')
M('E', 1, 'Which statement about magnetic flux density and magnetic flux is correct?', 'Flux density is a vector; flux is a scalar', ['Both are vectors', 'Both are scalars', 'Flux is a vector; flux density is a scalar'], 'B has a direction; Φ = BA cos θ is a single number for a given surface.')
N('E', 2, 'A Hall-probe check finds that a flux of 4.5 × 10⁻⁴ Wb passes face-on through a 3.0 × 10⁻³ m² loop. Find the flux density.', 4.5e-4 / 3.0e-3, 'T',
  'B = Φ/A = 4.5 × 10⁻⁴ ÷ 3.0 × 10⁻³ = 0.15 T', ['C1: B = Φ/A'], sig=2, aq='B')
M('E', 1, 'At most places on the Earth\'s surface, how is the Earth\'s magnetic field directed?', 'At an angle to the horizontal, so it has both horizontal and vertical components', ['Exactly horizontal', 'Exactly vertical', 'From south to north along the ground only'], 'The angle below the horizontal is called the angle of dip.')
N('E', 2, 'A 1.0 m length of wire carries 1.0 A at right angles to a field of 0.35 T. Calculate the force on it.', 0.35, 'N',
  'F = BIL = 0.35 × 1.0 × 1.0 = 0.35 N: numerically equal to B, as the definition of the tesla shows', ['C1: F = BIL'], sig=2, aq='F')
M('E', 1, 'What does the field between flat north and south poles facing each other look like?', 'Nearly uniform, with parallel lines from the north pole to the south pole', ['Concentric circles around the poles', 'Lines curving back into the north pole', 'No field, because the poles cancel'], 'Between close, flat, opposite poles the field is approximately uniform.')
N('E', 1, 'A 10-turn coil of area 0.010 m² lies face-on to a field of 0.020 T. Calculate the flux linkage.', 10 * 0.020 * 0.010, 'Wb', 'NΦ = NBA = 10 × 0.020 × 0.010 = 2.0 × 10⁻³ Wb', [], sig=2, aq='NΦ')
# medium
N('M', 3, 'At a location, the Earth\'s field is 50 µT and the angle of dip is 66°. Calculate the horizontal component of the field, in µT.', 50 * cos(radians(66)), 'µT',
  f'B_h = B cos 66° = 50 × cos 66° = {sf(50 * cos(radians(66)))} µT', ['C1: resolve with dip angle', 'C1: cosine for horizontal'], aq='B_h')
N('M', 3, 'The vertical component of the Earth\'s field is 45 µT. Calculate the flux through a horizontal roof of area 4.0 m².', 45e-6 * 4.0, 'Wb',
  'Only the vertical component passes through a horizontal surface: Φ = 45 × 10⁻⁶ × 4.0 = 1.8 × 10⁻⁴ Wb', ['C1: vertical component', 'C1: Φ = BA'], sig=2, aq='Φ')
N('M', 4, 'A 100-turn coil of area 0.0050 m² starts face-on to a 0.20 T field and is turned until its normal is at 60° to the field. Calculate the change in flux linkage.', 100 * 0.20 * 0.0050 * (1 - cos(radians(60))), 'Wb',
  'Δ(NΦ) = NBA(1 − cos 60°) = 100 × 0.20 × 0.0050 × (1 − 0.50) = 0.050 Wb', ['C1: NΦ = NBA cos θ', 'C1: initial and final values', 'C1: difference'], sig=2, aq='Δ(NΦ)')
M('M', 3, 'The area of a coil is doubled and the flux density is halved, with the coil face-on to the field each time. What happens to the flux through the coil?', 'It stays the same', ['It doubles', 'It halves', 'It quadruples'], 'Φ = BA, and doubling A while halving B leaves the product unchanged.', ['C1: Φ = BA', 'C1: product unchanged'])
N('M', 3, 'A circular coil of radius 3.0 cm lies face-on to a field of 0.40 T. Calculate the flux through it.', 0.40 * pi * 0.030 ** 2, 'Wb',
  f'A = π × 0.030² = {sf(pi * 0.03 ** 2)} m². Φ = 0.40 × {sf(pi * 0.03 ** 2, 4)} = {sf(0.4 * pi * 0.03 ** 2)} Wb', ['C1: A = πr²', 'C1: Φ = BA'], aq='Φ')
N('M', 3, 'What area must a coil have, face-on to a 0.25 T field, for the flux through it to be 2.0 × 10⁻³ Wb?', 2.0e-3 / 0.25, 'm²',
  'A = Φ/B = 2.0 × 10⁻³ ÷ 0.25 = 8.0 × 10⁻³ m²', ['C1: A = Φ/B', 'C1: substitution'], sig=2, aq='A')
M('M', 3, 'A coil of area A is in a uniform field B, and the normal to the coil makes angle θ with the field. Which expression gives the flux through it?', 'BA cos θ', ['BA sin θ', 'BA/cos θ', 'BA tan θ'], 'Only the component of B along the normal, B cos θ, passes through the coil.', ['C1: component along normal', 'C1: cos θ'])
N('M', 4, 'At what angle between the field and the normal to a coil is the flux through the coil half its maximum value?', degrees(acos(0.5)), '°',
  'Φ/Φ_max = cos θ = 0.50, so θ = cos⁻¹ 0.50 = 60°', ['M1: Φ = Φ_max cos θ', 'C1: cos θ = 0.50', 'C1: angle'], sig=2, aq='θ')
N('M', 3, 'The field inside a solenoid of radius 2.0 cm is 0.010 T. Calculate the flux through its cross-section.', 0.010 * pi * 0.020 ** 2, 'Wb',
  f'Φ = BA = 0.010 × π × 0.020² = {sf(0.01 * pi * 4e-4)} Wb', ['C1: A = πr²', 'C1: Φ = BA'], aq='Φ')
M('M', 3, 'Which statement defines the weber?', 'The flux through 1 m² when a field of 1 T passes at right angles through it', ['The flux density that gives 1 N on 1 m of wire carrying 1 A', 'The field produced by 1 A at 1 m', 'The flux through a coil of 1 turn in any field'], 'From Φ = BA with the field perpendicular to the surface: 1 Wb = 1 T × 1 m².', ['C1: Φ = BA', 'C1: perpendicular'])
N('M', 3, 'A 25 cm length of wire at right angles to a uniform field carries 4.0 A and feels a force of 0.15 N. Calculate the flux density, in mT.', 0.15 / (4.0 * 0.25) * 1000, 'mT',
  'B = F/(IL) = 0.15 ÷ (4.0 × 0.25) = 0.15 T. In mT: 0.15 × 1000 = 150', ['C1: B = F/(IL)', 'C1: conversion'], sig=2, aq='B')
N('M', 4, 'A 500-turn coil of area 0.010 m² is held horizontally where the vertical component of the Earth\'s field is 4.4 × 10⁻⁵ T. Calculate the flux linkage.', 500 * 4.4e-5 * 0.010, 'Wb',
  'NΦ = NB_vA = 500 × 4.4 × 10⁻⁵ × 0.010 = 2.2 × 10⁻⁴ Wb', ['B1: vertical component through horizontal coil', 'C1: NΦ = NBA', 'C1: substitution'], sig=2, aq='NΦ')
M('M', 3, 'Why can two magnetic field lines never cross?', 'The field has only one direction at each point, and the line\'s direction shows it', ['Field lines repel each other', 'Crossing would make the field zero', 'Field lines are made of magnetic material'], 'If lines crossed, a compass at the crossing would have to point two ways at once.', ['C1: unique direction at a point', 'C1: line shows that direction'])
N('M', 3, 'Calculate (flux through a coil whose normal is at 30° to the field) ÷ (flux when the coil is face-on).', cos(radians(30)), None,
  f'Ratio = cos 30° = {sf(cos(radians(30)))}', ['C1: Φ ∝ cos θ', 'C1: value'], aq='ratio')
M('M', 4, 'For a flat surface of area A at right angles to a uniform field, which statement is correct?', 'B = Φ/A, so flux density is flux per unit area', ['Φ = B/A', 'B = ΦA', 'Φ and B have the same unit'], 'This is why the tesla is also the weber per square metre.', ['C1: Φ = BA', 'C1: B = Φ/A', 'C1: T = Wb m⁻²'])
N('M', 3, 'A flux of 3.0 × 10⁻³ Wb passes through a loop of area 0.020 m² whose normal is at 40° to the field. Calculate the flux density.', 3.0e-3 / (0.020 * cos(radians(40))), 'T',
  f'B = Φ/(A cos θ) = 3.0 × 10⁻³ ÷ (0.020 × cos 40°) = {sf(3e-3 / (0.02 * cos(radians(40))))} T', ['C1: Φ = BA cos θ', 'C1: rearranged'], aq='B')
# hard
N('H', 6, 'A rectangular coil of 200 turns measuring 4.0 cm × 5.0 cm is in a uniform field of 0.15 T. (a) Calculate the maximum flux linkage. (b) Calculate the flux linkage when the coil has been turned 30° from that position. (c) Calculate the change in flux linkage as the coil turns from the maximum position until its plane is parallel to the field. Give only the answer to (b).', 200 * 0.15 * 0.040 * 0.050 * cos(radians(30)), 'Wb',
  f'(a) NBA = 200 × 0.15 × 0.040 × 0.050 = 0.060 Wb. (b) NΦ = 0.060 × cos 30° = {sf(0.06 * cos(radians(30)))} Wb. (c) The plane is then parallel, so NΦ = 0 and the change is 0.060 Wb.',
  ['C1: area in m²', 'C1: NBA', 'M1: × cos θ', 'C1: value', 'B1: change equals maximum'], aq='NΦ')
N('H', 5, 'At a certain place the Earth\'s horizontal field component is 1.9 × 10⁻⁵ T and the angle of dip is 68°. (a) Calculate the total flux density. (b) Calculate the vertical component. (c) Calculate the flux through a horizontal roof 1.5 m × 2.0 m. Give only the answer to (c).', 1.9e-5 / cos(radians(68)) * sin(radians(68)) * 3.0, 'Wb',
  f'(a) B = 1.9 × 10⁻⁵ ÷ cos 68° = {sf(1.9e-5 / cos(radians(68)))} T. (b) B_v = {sf(1.9e-5 / cos(radians(68)), 4)} × sin 68° = {sf(1.9e-5 * tan(radians(68)))} T. (c) Φ = {sf(1.9e-5 * tan(radians(68)), 4)} × 1.5 × 2.0 = {sf(1.9e-5 * tan(radians(68)) * 3)} Wb',
  ['C1: B = B_h/cos dip', 'C1: B_v = B sin dip', 'M1: vertical component through roof', 'C1: Φ = B_vA'], aq='Φ')
N('H', 6, 'A Hall probe is moved along the axis of a bar magnet: d/cm = 2.0, 4.0, 6.0, 8.0 and B/mT = 40, 5.0, 1.48, 0.625. (a) Show that B is not inversely proportional to d. (b) Show that Bd³ is constant. (c) Use your result to predict B at d = 10 cm, in mT. Give only the answer to (c).', 40 * 2.0 ** 3 / 10 ** 3, 'mT',
  '(a) Bd = 80 at 2.0 cm but 5.0 at 8.0 cm, so B is not ∝ 1/d. (b) Bd³ = 40 × 2.0³ = 320 and 0.625 × 8.0³ = 320 (also 5.0 × 4.0³ = 320), so Bd³ is constant. (c) B = 320 ÷ 10³ = 0.32 mT',
  ['B1: Bd not constant', 'C1: Bd³ values', 'B1: constant', 'M1: B = k/d³', 'C1: prediction'], sig=2, aq='B')
N('H', 5, 'A solenoid with no core gives a field of 2.0 mT. An iron core is inserted, increasing the field by a factor of 500. The core has a cross-sectional area of 2.0 × 10⁻⁴ m², and a 50-turn coil is wound round it. (a) Calculate the new flux density. (b) Calculate the flux in the core. (c) Calculate the flux linkage of the 50-turn coil. Give only the answer to (c).', 50 * 2.0e-3 * 500 * 2.0e-4, 'Wb',
  '(a) B = 500 × 2.0 × 10⁻³ = 1.0 T. (b) Φ = 1.0 × 2.0 × 10⁻⁴ = 2.0 × 10⁻⁴ Wb. (c) NΦ = 50 × 2.0 × 10⁻⁴ = 0.010 Wb',
  ['C1: new B', 'C1: Φ = BA', 'M1: same flux through the coil', 'C1: NΦ'], sig=2, aq='NΦ')
N('H', 6, 'A wire 0.050 m long carrying 2.0 A is placed at different angles θ to a uniform field: θ = 30°, 60°, 90° and F/mN = 12, 21, 24. (a) Show that the readings are consistent with F ∝ sin θ. (b) Calculate the flux density. (c) Predict the force at θ = 45°, in mN. Give only the answer to (b).', 24e-3 / (2.0 * 0.050), 'T',
  f'(a) F/sin θ = 12 ÷ sin 30° = 24, 21 ÷ sin 60° = {sf(21 / sin(radians(60)))} and 24 ÷ sin 90° = 24 mN: constant within error. (b) At 90°: B = F/(IL) = 24 × 10⁻³ ÷ (2.0 × 0.050) = 0.24 T. (c) F = 24 × sin 45° = {sf(24 * sin(radians(45)))} mN',
  ['C1: F/sin θ values', 'B1: constant', 'C1: B = F/(IL) at 90°', 'C1: substitution', 'C1: prediction'], sig=2, aq='B')
N('H', 5, 'Coil A has 100 turns of radius 2.0 cm; coil B has 25 turns of radius 4.0 cm. Both are face-on to the same uniform field. (a) Write the flux linkage of each in terms of B. (b) Calculate (flux linkage of A) ÷ (flux linkage of B). (c) Explain the result. Give only the answer to (b).', (100 * 0.02 ** 2) / (25 * 0.04 ** 2), None,
  '(a) NΦ_A = 100 × B × π × 0.020²; NΦ_B = 25 × B × π × 0.040². (b) Ratio = (100 × 0.020²) ÷ (25 × 0.040²) = 1.0. (c) B has four times the area per turn but a quarter of the turns.',
  ['C1: NΦ = NBπr²', 'C1: both expressions', 'C1: ratio', 'B1: area × turns equal'], sig=2, aq='ratio')
N('H', 5, 'A rectangular loop 0.10 m × 0.20 m lies flat. Half of its area is in a field of 0.20 T pointing upwards and the other half is in a field of 0.050 T pointing downwards. (a) Calculate the flux through each half. (b) Calculate the net flux through the loop. (c) Explain why the fluxes are combined with opposite signs. Give only the answer to (b).', (0.20 - 0.050) * 0.010, 'Wb',
  '(a) Each half has area 0.010 m²: Φ₁ = 0.20 × 0.010 = 2.0 × 10⁻³ Wb up; Φ₂ = 0.050 × 0.010 = 5.0 × 10⁻⁴ Wb down. (b) Net Φ = 2.0 × 10⁻³ − 5.0 × 10⁻⁴ = 1.5 × 10⁻³ Wb. (c) Flux is counted relative to a chosen normal; field passing the opposite way counts as negative.',
  ['C1: area of each half', 'C1: each flux', 'M1: subtract opposite fluxes', 'B1: sign convention'], sig=2, aq='Φ')
N('H', 5, 'A 50-turn rectangular coil 0.30 m × 0.20 m lies flat on a table where the vertical component of the Earth\'s field is 44 µT. The coil is flipped over. (a) Calculate the initial flux linkage. (b) Explain why the flux linkage changes sign when the coil is flipped. (c) Calculate the magnitude of the change in flux linkage. Give only the answer to (c).', 2 * 50 * 44e-6 * 0.30 * 0.20, 'Wb',
  f'(a) NΦ = 50 × 44 × 10⁻⁶ × 0.30 × 0.20 = {sf(50 * 44e-6 * 0.06)} Wb. (b) The field now enters the opposite face of the coil, relative to its normal. (c) Change = 2 × {sf(50 * 44e-6 * 0.06, 4)} = {sf(2 * 50 * 44e-6 * 0.06)} Wb',
  ['C1: NBA', 'B1: reversal relative to normal', 'M1: change = 2NBA', 'C1: value'], aq='Δ(NΦ)')
N('H', 5, '(a) Show that 1 T = 1 N A⁻¹ m⁻¹ and hence that 1 Wb = 1 N m A⁻¹. (b) A field of 0.40 T passes at right angles through an area of 25 cm². Calculate the flux. Give only the answer to (b).', 0.40 * 25e-4, 'Wb',
  '(a) B = F/(IL) gives T = N A⁻¹ m⁻¹; Φ = BA gives Wb = N A⁻¹ m⁻¹ × m² = N m A⁻¹. (b) 25 cm² = 25 × 10⁻⁴ m², so Φ = 0.40 × 25 × 10⁻⁴ = 1.0 × 10⁻³ Wb',
  ['B1: tesla from F = BIL', 'B1: weber from Φ = BA', 'C1: cm² to m²', 'C1: Φ = BA'], sig=2, aq='Φ')
N('H', 5, 'A small 30-turn coil of area 1.5 cm² is placed inside a solenoid where the field is 8.0 mT, with the normal to the coil at 25° to the solenoid\'s axis. (a) Calculate the flux through one turn. (b) Calculate the flux linkage. (c) State the orientation that would make the flux linkage zero. Give only the answer to (b).', 30 * 8.0e-3 * 1.5e-4 * cos(radians(25)), 'Wb',
  f'(a) Φ = 8.0 × 10⁻³ × 1.5 × 10⁻⁴ × cos 25° = {sf(8e-3 * 1.5e-4 * cos(radians(25)))} Wb. (b) NΦ = 30 × {sf(8e-3 * 1.5e-4 * cos(radians(25)), 4)} = {sf(30 * 8e-3 * 1.5e-4 * cos(radians(25)))} Wb. (c) With the plane of the coil parallel to the axis (normal at 90°).',
  ['C1: area in m²', 'C1: Φ = BA cos θ', 'C1: NΦ', 'B1: plane parallel to field'], aq='NΦ')

# ═════════════════════════ 24.4 Measuring magnetic flux density (17/16/11) ═════════════════════════
lesson('24.4')
M('E', 1, 'What does the output voltage of a Hall probe depend on?', 'The component of the magnetic flux density at right angles to the probe\'s flat face', ['The total current in the circuit being tested', 'The temperature of the magnet only', 'The electric field around the probe'], 'The Hall voltage is proportional to the perpendicular component of B.')
N('E', 2, 'When a current flows through a wire between the poles of a magnet resting on a top-pan balance, the reading changes by 1.5 g. Calculate the size of the force on the wire.' + take('g'), 1.5e-3 * g, 'N',
  'F = Δm × g = 1.5 × 10⁻³ × 9.81 = 0.0147 N', ['C1: convert grams to kg and × g'], aq='F')
N('E', 2, 'A 0.040 m length of wire at right angles to a field carries 2.5 A and feels a force of 0.020 N. Calculate the flux density.', 0.020 / (2.5 * 0.040), 'T',
  'B = F/(IL) = 0.020 ÷ (2.5 × 0.040) = 0.20 T', ['C1: B = F/(IL)'], sig=2, aq='B')
M('E', 1, 'A magnet sits on a top-pan balance with a fixed wire passing between its poles. When a current flows, the reading increases. Why?', 'The magnet pushes up on the wire, so by Newton\'s third law the wire pushes down on the magnet', ['The current adds weight to the wire', 'The magnet becomes heavier', 'The balance is affected by the current directly'], 'The forces on wire and magnet are equal and opposite.')
M('E', 1, 'How should a Hall probe be held to give its maximum reading?', 'With its flat face at right angles to the field lines', ['With its flat face parallel to the field lines', 'Pointing towards the north pole', 'At 45° to the field'], 'Only the perpendicular component of B produces the Hall voltage.')
N('E', 2, 'A calibrated Hall probe gives 1.0 mV for every 1.0 mT. Its reading near a magnet is 35 mV. What is the flux density, in mT?', 35, 'mT',
  'B = 35 ÷ 1.0 = 35 mT', ['C1: reading ÷ sensitivity'], sig=2, aq='B')
M('E', 1, 'In a top-pan balance experiment, why are readings also taken with the current reversed?', 'To check that the change reverses, so that effects not due to the magnetic force can be averaged out', ['To double the current', 'To demagnetise the magnet', 'To keep the wire cool'], 'Reversing the current reverses only the magnetic force, so averaging the two changes removes zero errors.')
N('E', 2, 'A wire carrying 3.0 A crosses a 5.0 cm wide magnetic field at right angles. The balance reading changes by 0.92 g. Calculate the flux density.' + take('g'), 0.92e-3 * g / (3.0 * 0.050), 'T',
  f'F = 0.92 × 10⁻³ × 9.81 = {sf(0.92e-3 * 9.81)} N. B = F/(IL) = {sf(0.92e-3 * 9.81, 4)} ÷ (3.0 × 0.050) = {sf(0.92e-3 * 9.81 / 0.15)} T', ['C1: F = Δm g, then B = F/(IL)'], aq='B')
M('E', 1, 'Compared with a current balance, what is an advantage of a Hall probe?', 'It measures the field at a point, so it can map how the field varies', ['It needs no electrical supply', 'It averages the field over a long length', 'It measures the current in the wire'], 'The probe\'s sensor is tiny, so it samples a small region.')
N('E', 2, 'A 0.060 m length of wire carrying 4.0 A lies at right angles to a field of 50 mT. Calculate the force on it.', 50e-3 * 4.0 * 0.060, 'N',
  'F = BIL = 50 × 10⁻³ × 4.0 × 0.060 = 0.012 N', ['C1: F = BIL'], sig=2, aq='F')
M('E', 1, 'A Hall probe is turned so that its face is at an angle to the field. How does its reading change?', 'It decreases, because only the perpendicular component of B is measured', ['It increases', 'It stays the same', 'It reverses'], 'The reading is proportional to B cos θ, where θ is between B and the normal to the face.')
N('E', 2, 'A balance reading changes from 152.40 g to 151.88 g when a current is switched on. Calculate the size of the magnetic force, in mN.' + take('g'), (152.40 - 151.88) * 1e-3 * g * 1000, 'mN',
  f'Δm = 152.40 − 151.88 = 0.52 g. F = 0.52 × 10⁻³ × 9.81 = {sf(0.52e-3 * 9.81)} N. In mN: {sf(0.52e-3 * 9.81, 4)} × 1000 = {sf(0.52e-3 * 9.81 * 1000)}', ['C1: F = Δm g'], aq='F')
M('E', 1, 'Which three quantities must be measured to find B with a current balance?', 'The force on the wire, the current, and the length of wire in the field', ['The voltage, the resistance and the time', 'The mass of the magnet, its length and its temperature', 'The charge, the speed and the radius'], 'B = F/(IL), so F, I and L are all needed, with the wire at right angles to the field.')
N('E', 2, 'A Hall probe gives an output of 0.24 V in a known field of 0.40 T. What output, in V, would it give in a field of 0.15 T?', 0.24 * 0.15 / 0.40, 'V',
  'Output ∝ B: 0.24 × 0.15 ÷ 0.40 = 0.090 V', ['C1: output proportional to B'], sig=2, aq='V')
M('E', 1, 'Why is the reading with no current flowing recorded before a top-pan balance experiment?', 'It is the zero reading: only the change from it is due to the magnetic force', ['To measure the Earth\'s field', 'To find the current', 'To calibrate the ammeter'], 'The force is found from the change in reading.')
N('E', 1, 'In a balance experiment the magnetic force is 4.0 mN at a certain current. What is the force, in mN, when the current is doubled?', 8.0, 'mN', 'F ∝ I: 2 × 4.0 = 8.0 mN', [], sig=2, aq='F')
N('E', 2, 'A Hall probe reads 4.2 mT when the field makes an angle of 30° with the normal to its face. Calculate the actual flux density, in mT.', 4.2 / cos(radians(30)), 'mT',
  f'B = reading ÷ cos 30° = 4.2 ÷ cos 30° = {sf(4.2 / cos(radians(30)))} mT', ['C1: reading = B cos θ'], aq='B')
# medium
N('M', 3, 'With a current of 3.0 A, the top-pan balance reading changes by 2.4 g. The length of wire in the field is 0.050 m. Calculate the flux density.' + take('g'), 2.4e-3 * g / (3.0 * 0.050), 'T',
  f'F = 2.4 × 10⁻³ × 9.81 = {sf(2.4e-3 * 9.81)} N. B = {sf(2.4e-3 * 9.81, 4)} ÷ (3.0 × 0.050) = {sf(2.4e-3 * 9.81 / 0.15)} T', ['C1: F = Δm g', 'C1: B = F/(IL)'], aq='B')
N('M', 4, 'In a current balance experiment, the force is measured to ±2 %, the current to ±1 % and the length of wire in the field to ±2 %. Calculate the percentage uncertainty in B.', 2 + 1 + 2, '%',
  'B = F/(IL): percentage uncertainties add, 2 + 1 + 2 = 5.0 %', ['M1: product and quotient rule', 'C1: percentages add', 'C1: value'], sig=2, aq='uncertainty')
M('M', 3, 'In a top-pan balance experiment the reading increases when the current flows. When the current is reversed, what happens?', 'The reading decreases below the zero value by the same amount', ['The reading increases by twice as much', 'The reading stays the same', 'The reading returns to zero'], 'Reversing the current reverses the force on the wire and so on the magnet.', ['C1: force reverses', 'C1: same magnitude'])
N('M', 3, 'A Hall probe reads 6.3 mT inside a solenoid carrying 2.5 A. What will it read when the current is increased to 4.0 A, in mT?', 6.3 * 4.0 / 2.5, 'mT',
  f'B ∝ I: 6.3 × 4.0 ÷ 2.5 = {sf(6.3 * 4 / 2.5)} mT', ['C1: B ∝ I', 'C1: substitution'], aq='B')
N('M', 3, 'A graph of force against current for a wire at right angles to a field has a gradient of 0.012 N A⁻¹. The length of wire in the field is 0.060 m. Calculate the flux density.', 0.012 / 0.060, 'T',
  'F = BIL, so the gradient = BL and B = 0.012 ÷ 0.060 = 0.20 T', ['M1: gradient = BL', 'C1: B'], sig=2, aq='B')
M('M', 3, 'Why should the whole length of wire used in the force calculation lie in the uniform region between the pole pieces?', 'So that B is the same along the whole length L used in F = BIL', ['So that the current is larger', 'So that the wire does not heat up', 'So that the Earth\'s field is cancelled'], 'Near the edges the field is weaker and non-uniform, so F would not equal BIL for the full L.', ['C1: uniform B along L', 'C1: edge effects'])
N('M', 4, 'A magnet assembly reads 120.00 g on a top-pan balance. With 4.0 A in a wire that crosses its field for 0.040 m, the reading becomes 121.32 g. Calculate the flux density.' + take('g'), 1.32e-3 * g / (4.0 * 0.040), 'T',
  f'Δm = 121.32 − 120.00 = 1.32 g. F = 1.32 × 10⁻³ × 9.81 = {sf(1.32e-3 * 9.81)} N. B = {sf(1.32e-3 * 9.81, 4)} ÷ (4.0 × 0.040) = {sf(1.32e-3 * 9.81 / 0.16)} T', ['C1: change in reading', 'C1: F = Δm g', 'C1: B = F/(IL)'], aq='B')
N('M', 3, 'A Hall probe gives 0.85 V in a field of 0.17 T. In an unknown field it gives 0.50 V. Calculate the unknown flux density.', 0.17 * 0.50 / 0.85, 'T',
  'Output ∝ B: B = 0.17 × 0.50 ÷ 0.85 = 0.10 T', ['C1: proportionality', 'C1: substitution'], sig=2, aq='B')
M('M', 3, 'Why is a Hall probe better than a current balance for investigating how the field varies across the gap of a magnet?', 'It is small and measures B at a point, so readings can be taken at many positions', ['It measures the force directly', 'It does not need calibrating', 'It averages B over the whole gap'], 'A current balance gives an average over the length of wire.', ['C1: point measurement', 'C1: can map field'])
N('M', 3, 'In a pivoted current balance, the magnetic force on a wire 8.0 cm from the pivot is balanced by a rider of mass 0.50 g placed 4.0 cm from the pivot. The wire carries 2.0 A and has 0.050 m in the field. Calculate the flux density, in mT.' + take('g'), 0.50e-3 * g * 0.040 / 0.080 / (2.0 * 0.050) * 1000, 'mT',
  f'Moments: F × 0.080 = 0.50 × 10⁻³ × 9.81 × 0.040, so F = {sf(0.5e-3 * 9.81 * 0.04 / 0.08)} N. B = {sf(0.5e-3 * 9.81 * 0.04 / 0.08, 4)} ÷ (2.0 × 0.050) = {sf(0.5e-3 * 9.81 * 0.04 / 0.08 / 0.1)} T. In mT: {sf(0.5e-3 * 9.81 * 0.04 / 0.08 / 0.1, 4)} × 1000 = {sf(0.5e-3 * 9.81 * 0.04 / 0.08 / 0.1 * 1000)}', ['M1: principle of moments', 'C1: B = F/(IL)'], aq='B')
M('M', 4, 'In a current balance experiment using a strong magnet, why can the Earth\'s magnetic field usually be ignored?', 'It is about 5 × 10⁻⁵ T, thousands of times smaller than the magnet\'s field', ['It acts only on iron', 'It is cancelled by the current', 'It is always parallel to the wire'], 'A typical magnet gives about 0.1 T, so the Earth\'s contribution is under 0.1 %.', ['C1: Earth field ~10⁻⁵ T', 'C1: magnet ~0.1 T', 'C1: negligible ratio'])
N('M', 3, 'A wire with 0.050 m in a field of 0.10 T is to change a balance reading by 1.0 g. Calculate the current needed.' + take('g'), 1.0e-3 * g / (0.10 * 0.050), 'A',
  f'F = 1.0 × 10⁻³ × 9.81 = 9.81 × 10⁻³ N. I = F/(BL) = 9.81 × 10⁻³ ÷ (0.10 × 0.050) = {sf(9.81e-3 / 0.005)} A', ['C1: F = Δm g', 'C1: I = F/(BL)'], aq='I')
N('M', 4, 'A solenoid has 1500 turns per metre and carries 1.3 A. Calculate the flux density predicted by B = µ₀nI, in mT, for comparison with a Hall-probe reading.' + MUS, MU0 * 1500 * 1.3 * 1000, 'mT',
  f'B = 4π × 10⁻⁷ × 1500 × 1.3 = {sf(MU0 * 1950)} T. In mT: {sf(MU0 * 1950, 4)} × 1000 = {sf(MU0 * 1950 * 1000)}', ['C1: B = µ₀nI', 'C1: substitution', 'C1: conversion'], aq='B')
M('M', 3, 'A Hall probe in a uniform field is slowly rotated. In which position does its reading fall to zero?', 'When its flat face is parallel to the field lines', ['When its face is perpendicular to the field', 'When it points at the north pole', 'It never reads zero in a field'], 'Then the field has no component perpendicular to the face.', ['C1: perpendicular component zero', 'C1: face parallel to B'])
N('M', 3, 'With the current one way the balance reads 100.62 g; with it reversed the reading is 99.38 g. Calculate the magnetic force, in mN.' + take('g'), (100.62 - 99.38) / 2 * 1e-3 * g * 1000, 'mN',
  f'The change each way is (100.62 − 99.38) ÷ 2 = 0.62 g. F = 0.62 × 10⁻³ × 9.81 = {sf(0.62e-3 * 9.81)} N. In mN: {sf(0.62e-3 * 9.81, 4)} × 1000 = {sf(0.62e-3 * 9.81 * 1000)}', ['M1: half the difference', 'C1: F = Δm g'], aq='F')
N('M', 3, 'A wire in a current balance is accidentally set at 60° to the field. With 3.0 A and 0.050 m in the field, the force is 0.026 N. Calculate the flux density.', 0.026 / (3.0 * 0.050 * sin(radians(60))), 'T',
  f'B = F/(IL sin θ) = 0.026 ÷ (3.0 × 0.050 × sin 60°) = {sf(0.026 / (0.15 * sin(radians(60))))} T', ['C1: F = BIL sin θ', 'C1: rearranged'], aq='B')
# hard
N('H', 6, 'In a top-pan balance experiment, the length of wire in the field is 0.050 m. Results: I/A = 0.5, 1.0, 1.5, 2.0, 2.5 and change in reading Δm/g = 0.31, 0.61, 0.92, 1.22, 1.53. (a) Describe the relationship shown. (b) Calculate the gradient of the Δm–I graph. (c) Use the gradient to calculate B. Give only the answer to (c).' + take('g'), (1.53 - 0.31) / 2.0 * 1e-3 * g / 0.050, 'T',
  f'(a) Δm ∝ I. (b) Gradient = (1.53 − 0.31) ÷ (2.5 − 0.5) = 0.61 g A⁻¹. (c) F = Δm g = BIL, so B = gradient × g ÷ L = 0.61 × 10⁻³ × 9.81 ÷ 0.050 = {sf(0.61e-3 * 9.81 / 0.05)} T',
  ['B1: proportional', 'C1: gradient', 'M1: gradient × g = BL', 'C1: units converted', 'C1: B'], aq='B')
N('H', 5, 'In a top-pan balance experiment: Δm = 1.20 ± 0.02 g, I = 2.00 ± 0.05 A and L = 4.0 ± 0.1 cm. (a) Calculate B. (b) Calculate the percentage uncertainty in B. Give only the answer to (b), in %.' + take('g'), (0.02 / 1.20 + 0.05 / 2.00 + 0.1 / 4.0) * 100, '%',
  f'(a) B = 1.20 × 10⁻³ × 9.81 ÷ (2.00 × 0.040) = {sf(1.2e-3 * 9.81 / 0.08)} T. (b) Percentage uncertainty = (0.02 ÷ 1.20 + 0.05 ÷ 2.00 + 0.1 ÷ 4.0) × 100 = {sf((0.02 / 1.2 + 0.025 + 0.025) * 100)} %',
  ['C1: B = Δm g/(IL)', 'C1: each percentage', 'M1: add percentages', 'C1: value'], sig=2, aq='uncertainty')
N('H', 6, 'A Hall probe is moved along the axis of a long solenoid that carries 2.0 A. It reads 5.0 mT near the centre and about 2.5 mT at each end. (a) Explain why the field at the ends is about half the central value. (b) Use B = µ₀nI to calculate the number of turns per metre. Give only the answer to (b).' + MUS, 5.0e-3 / (MU0 * 2.0), 'm⁻¹',
  f'(a) At an end there are turns on one side only, so only about half of the contributions are present. (b) n = B/(µ₀I) = 5.0 × 10⁻³ ÷ (4π × 10⁻⁷ × 2.0) = {sf(5e-3 / (MU0 * 2))} m⁻¹',
  ['B1: turns on one side only', 'B1: half the contribution', 'M1: n = B/(µ₀I)', 'C1: substitution', 'C1: value'], aq='n')
N('H', 5, 'A wire frame on knife edges carries 2.5 A, with a 6.0 cm side at right angles to a magnetic field. The magnetic force on that side is balanced by a 0.20 g mass hung on the same side of the frame at the same distance from the pivot. (a) Explain why the force on the wire equals the weight of the mass. (b) Calculate the flux density, in mT. Give only the answer to (b).' + take('g'), 0.20e-3 * g / (2.5 * 0.060) * 1000, 'mT',
  f'(a) Both act at the same distance from the pivot, so equal moments need equal forces. (b) B = mg/(IL) = 0.20 × 10⁻³ × 9.81 ÷ (2.5 × 0.060) = {sf(0.2e-3 * 9.81 / 0.15)} T. In mT: {sf(0.2e-3 * 9.81 / 0.15, 4)} × 1000 = {sf(0.2e-3 * 9.81 / 0.15 * 1000)}',
  ['B1: equal moments at equal distance', 'C1: weight in N', 'C1: B = F/(IL)', 'C1: conversion'], aq='B')
N('H', 6, 'A Hall probe gives 18 mV inside a long solenoid with 2400 turns per metre carrying 1.5 A. It then gives 27 mV between the poles of a magnet. (a) Calculate the field inside the solenoid using B = µ₀nI. (b) Calculate the probe\'s sensitivity in mV per mT. (c) Calculate the flux density between the poles, in mT. Give only the answer to (c).' + MUS, 27 / (18 / (MU0 * 2400 * 1.5 * 1000)), 'mT',
  f'(a) B = 4π × 10⁻⁷ × 2400 × 1.5 = {sf(MU0 * 3600)} T, which is {sf(MU0 * 3600 * 1000)} mT. (b) Sensitivity = 18 ÷ {sf(MU0 * 3600 * 1000, 4)} = {sf(18 / (MU0 * 3600 * 1000))} mV per mT. (c) B = 27 ÷ {sf(18 / (MU0 * 3600 * 1000), 4)} = {sf(27 / (18 / (MU0 * 3600 * 1000)))} mT',
  ['C1: B = µ₀nI', 'C1: in mT', 'M1: sensitivity = output/B', 'C1: B = output/sensitivity', 'B1: calibration idea'], aq='B')
N('H', 5, 'A student tries to measure the Earth\'s horizontal field with a current balance. A 1.5 m horizontal wire carries 20 A east–west where the horizontal field is 1.8 × 10⁻⁵ T. (a) Calculate the force on the wire, in mN. (b) The balance can resolve 0.01 g. Calculate the percentage uncertainty this gives in the force. Give only the answer to (a).' + take('g'), 1.8e-5 * 20 * 1.5 * 1000, 'mN',
  f'(a) F = BIL = 1.8 × 10⁻⁵ × 20 × 1.5 = {sf(1.8e-5 * 30)} N. In mN: {sf(1.8e-5 * 30)} × 1000 = {sf(1.8e-5 * 30 * 1000)}. (b) Resolution = 0.01 × 10⁻³ × 9.81 = 9.81 × 10⁻⁵ N, so the uncertainty = 9.81 × 10⁻⁵ ÷ {sf(1.8e-5 * 30)} × 100 = {sf(9.81e-5 / (1.8e-5 * 30) * 100)} %: far too large for a useful measurement.',
  ['C1: F = BIL', 'C1: conversion', 'C1: resolution as a force', 'C1: percentage uncertainty'], aq='F')
N('H', 6, 'Hall-probe readings across the 5.0 cm gap between two pole pieces, at the midpoints of 1.0 cm intervals, are B/T = 0.10, 0.18, 0.20, 0.18, 0.10. A wire carrying 3.0 A crosses the gap at right angles to the field. (a) Explain why F ≠ B_max IL. (b) Estimate the force on the wire by adding the forces on each 1.0 cm section. (c) Calculate the average flux density over the gap. Give only the answer to (b).', 3.0 * 0.010 * (0.10 + 0.18 + 0.20 + 0.18 + 0.10), 'N',
  '(a) The field is not uniform: it is weaker near the edges. (b) F = IΣBΔx = 3.0 × 0.010 × (0.10 + 0.18 + 0.20 + 0.18 + 0.10) = 0.0228 N. (c) Average B = (0.10 + 0.18 + 0.20 + 0.18 + 0.10) ÷ 5 = 0.152 T',
  ['B1: non-uniform field', 'M1: sum of BIΔx', 'C1: substitution', 'C1: force', 'C1: average B'], aq='F')
N('H', 5, 'A current balance gives B = 0.152 T for the field between two pole pieces, while a Hall probe at the centre of the gap reads 0.160 T. (a) Calculate the percentage difference between the two values, relative to the Hall-probe value. (b) Explain why the current balance gives a smaller value. Give only the answer to (a), in %.', (0.160 - 0.152) / 0.160 * 100, '%',
  '(a) (0.160 − 0.152) ÷ 0.160 × 100 = 5.0 %. (b) The balance measures the average field along the wire, which includes the weaker field near the edges; the probe measures the strongest field, at the centre.',
  ['C1: difference', 'C1: percentage', 'B1: balance averages along L', 'B1: probe at the centre where B is largest'], sig=2, aq='difference')
N('H', 6, 'A student wants to measure a field of about 50 mT with a top-pan balance that reads to 0.01 g. The length of wire in the field is 5.0 cm. The uncertainty from the balance must be no more than 2 % of the force. (a) Calculate the smallest force that meets this requirement. (b) Calculate the smallest current needed. Give only the answer to (b).' + take('g'), (0.01e-3 * g / 0.02) / (50e-3 * 0.050), 'A',
  f'(a) Resolution = 0.01 × 10⁻³ × 9.81 = 9.81 × 10⁻⁵ N, which must be ≤ 2 % of F: F ≥ 9.81 × 10⁻⁵ ÷ 0.02 = {sf(9.81e-5 / 0.02)} N. (b) I = F/(BL) = {sf(9.81e-5 / 0.02, 4)} ÷ (50 × 10⁻³ × 0.050) = {sf(9.81e-5 / 0.02 / 2.5e-3)} A',
  ['C1: resolution as force', 'M1: resolution ≤ 2 % of F', 'C1: minimum F', 'C1: I = F/(BL)', 'C1: value'], aq='I')
N('H', 5, 'A wire in a current balance is at 70° to the field. With 2.5 A and 0.10 m in the field the measured force is 0.047 N. (a) Calculate the true flux density. (b) Calculate the value a student would get by wrongly assuming the wire was at 90°. (c) Calculate the percentage error this would cause. Give only the answer to (a).', 0.047 / (2.5 * 0.10 * sin(radians(70))), 'T',
  f'(a) B = 0.047 ÷ (2.5 × 0.10 × sin 70°) = {sf(0.047 / (0.25 * sin(radians(70))))} T. (b) B = 0.047 ÷ (2.5 × 0.10) = 0.188 T. (c) Error = (1 − sin 70°) × 100 = {sf((1 - sin(radians(70))) * 100)} %',
  ['C1: F = BIL sin θ', 'C1: true B', 'C1: wrong B', 'C1: percentage error'], aq='B')
N('H', 6, 'A magnet assembly on a top-pan balance reads 150.00 g. A wire crossing its field for 4.0 cm carries 3.0 A, and the reading rises to 150.65 g. (a) Calculate the force on the magnet. (b) Calculate the flux density. (c) State the direction of the force on the wire. (d) Predict the reading when the current is 1.0 A. Give only the answer to (b).' + take('g'), 0.65e-3 * g / (3.0 * 0.040), 'T',
  f'(a) F = 0.65 × 10⁻³ × 9.81 = {sf(0.65e-3 * 9.81)} N, downwards on the magnet. (b) B = {sf(0.65e-3 * 9.81, 4)} ÷ (3.0 × 0.040) = {sf(0.65e-3 * 9.81 / 0.12)} T. (c) Upwards: equal and opposite to the force on the magnet. (d) F ∝ I, so the change is 0.65 ÷ 3 = 0.22 g and the reading is 150.22 g.',
  ['C1: F = Δm g', 'C1: B = F/(IL)', 'B1: Newton\'s third law', 'C1: change ∝ I', 'C1: new reading'], aq='B')
